package com.app.controller;import com.app.dto.*;import com.app.dto.SocietyAttendanceDtos.AttendanceRow;import com.app.security.UserPrincipal;import com.app.service.SocietyAttendanceSelfServiceService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/society/attendance/self") @RequiredArgsConstructor public class SocietyAttendanceSelfServiceController {private final SocietyAttendanceSelfServiceService service;@GetMapping public List<AttendanceRow> mine(@AuthenticationPrincipal UserPrincipal p){return service.mine(p.getAccountId(),p.getUserId());}@PostMapping public List<AttendanceRow> record(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody SocietyAttendanceSelfServiceRequest r){return service.record(p.getAccountId(),p.getUserId(),r);}}
